f[x_] := Log[Tan[3 x]]; a = Pi/9;
ytan[x_] = f[a] + f'[a] (x - a);
ynor[x_] = f[a] - 1/f'[a] (x - a);
N[ytan[1], 6]
Solve[ynor[x] == 0, x] // N

F[x_, y_, z_] := {y z, x z, x y + 2 z}
r = {Cos[t], Sin[t], t};
integrando = F[Cos[t], Sin[t], t] . D[r, t]
NIntegrate[integrando, {t, 0, Pi/2}]
Curl[F[x, y, z], {x, y, z}]

sol = DSolve[y'[t] + 2 y[t] == t, y[t], t]
z[t_, c_] = y[t] /. Flatten[sol] /. C[1] -> c;
p1 = Plot[Evaluate[Table[z[t, c], {c, -2, 2}]], {t, -1, 2}, PlotRange -> {-2, 2}];
p2 = VectorPlot[{1, t - 2 y}, {t, -1, 2}, {y, -2, 2}];
Show[p1, p2]

yp[x_] = A + B x + C1 x^2;
res = D[yp[x], {x, 2}] - 4 yp[x] - (2 x^2 + x - 1);
Collect[res, x]
sol = Solve[CoefficientList[res, x] == {0, 0, 0}, {A, B, C1}]
yp[x] /. Flatten[sol]

y[x_] = Sum[a[k] x^k, {k, 0, 5}];
res = D[y[x], {x, 2}] - 2 x D[y[x], x] - 2 y[x];
coefs = Take[CoefficientList[res, x], 4]
sol = Solve[coefs == {0, 0, 0, 0}, {a[2], a[3], a[4], a[5]}]
y[x] /. Flatten[sol]

L = 5; phi[x_] = x (L - x);
An[n_Integer] := (2/L) Integrate[phi[x] Sin[n Pi x/L], {x, 0, L}]
u[x_, t_] = Sum[An[n] Exp[-4 (n Pi/L)^2 t] Sin[n Pi x/L], {n, 1, 5}];
N[u[3, 1/10]]
FindRoot[u[3, t] == 1, {t, 0.5}]
